package com.lexiscan.nlp; import com.lexiscan.analysis.*; import org.springframework.context.annotation.Primary; import org.springframework.stereotype.Service; import java.util.*; import java.util.regex.*; import java.util.stream.*;
@Service @Primary public class JavaNlpAnalysisService implements NlpAnalysisService { final RiskRuleRepository rules; public JavaNlpAnalysisService(RiskRuleRepository r){rules=r;} static final Map<String,List<String>> CATS=Map.of("PAYMENT",List.of("payment","rent","fee","salary","amount"),"TERMINATION",List.of("terminate","termination","notice"),"CONFIDENTIALITY",List.of("confidential","disclose"),"LIABILITY",List.of("liability","liable"),"INDEMNITY",List.of("indemnif"),"RENEWAL",List.of("renew","extension"),"NON_COMPETE",List.of("non-compete","compete"),"GOVERNING_LAW",List.of("governing law","jurisdiction"),"INTELLECTUAL_PROPERTY",List.of("intellectual property","ownership"),"DURATION",List.of("term","duration","months","years")); public AnalysisOutput analyze(String raw){String text=raw.replaceAll("-\\s*\\n","").replaceAll("\\s+"," ").trim();var parts=Arrays.stream(text.split("(?=(?:\\b(?:section|article|clause)\\s+\\d+|\\d+(?:\\.\\d+)*[.)]|[A-Z][A-Z ]{4,}:))",-1)).map(String::trim).filter(s->s.length()>25).toList();if(parts.isEmpty())parts=List.of(text);var clauses=new ArrayList<AnalysisOutput.ClauseOutput>();int high=0,total=0;for(int i=0;i<parts.size();i++){var c=parts.get(i);String cat=category(c);int score=0;String reason="No significant risk pattern matched";for(var r:rules.findByActiveTrue())try{if(Pattern.compile(r.getPattern(),Pattern.CASE_INSENSITIVE).matcher(c).find()){score=Math.max(score,r.getWeight());reason=r.getExplanation();}}catch(Exception ignored){} if(Pattern.compile("unlimited liability|sole discretion|non-refundable|automatic renewal|36%|three years",Pattern.CASE_INSENSITIVE).matcher(c).find())score=Math.max(score,75);String level=score>=70?"HIGH":score>=35?"MEDIUM":"LOW";if(score>=70)high++;total+=score;clauses.add(new AnalysisOutput.ClauseOutput(i+1,c,cat,level,score,reason));}int overall=Math.min(100,clauses.isEmpty()?0:(int)Math.round(total/(double)clauses.size()));String level=overall>=70?"HIGH":overall>=35?"MEDIUM":"LOW";return new AnalysisOutput(summary(clauses),overall,level,entities(text),clauses);} String category(String c){String l=c.toLowerCase();return CATS.entrySet().stream().max(Comparator.comparingInt(e->(int)e.getValue().stream().filter(l::contains).count())).filter(e->e.getValue().stream().anyMatch(l::contains)).map(Map.Entry::getKey).orElse("GENERAL");} Map<String,Object> entities(String t){Map<String,Object> m=new LinkedHashMap<>();m.put("parties",matches(t,"(?i)(?:between|landlord|tenant|employer|employee)\\s+([A-Z][A-Za-z &.]+)"));m.put("dates",matches(t,"\\b(?:\\d{1,2}[/-]\\d{1,2}[/-]\\d{2,4}|\\d{1,2}(?:st|nd|rd|th)?\\s+(?:January|February|March|April|May|June|July|August|September|October|November|December)\\s+\\d{4})\\b"));m.put("amounts",matches(t,"(?i)(?:rs\\.?|inr|usd|\\$)\\s?[\\d,]+(?:\\.\\d+)?(?:\\s*(?:lakh|crore))?"));m.put("durations",matches(t,"(?i)\\b\\d+\\s+(?:days?|months?|years?)\\b"));m.put("percentages",matches(t,"\\b\\d+(?:\\.\\d+)?%"));m.put("jurisdiction",matches(t,"(?i)(?:courts? of|jurisdiction of)\\s+([A-Za-z ]+)"));return m;} List<String> matches(String t,String p){var x=new ArrayList<String>();var m=Pattern.compile(p).matcher(t);while(m.find()&&x.size()<12)x.add(m.group());return x;} String summary(List<AnalysisOutput.ClauseOutput> c){return "Overview: This document contains "+c.size()+" clauses. Key details: review parties, dates and payments. Main obligations: "+c.stream().filter(x->!x.category().equals("GENERAL")).limit(3).map(AnalysisOutput.ClauseOutput::category).collect(Collectors.joining(", "))+". Things to watch out for: "+c.stream().filter(x->x.riskScore()>=35).limit(3).map(AnalysisOutput.ClauseOutput::riskReason).collect(Collectors.joining("; "));} }


